args.content:
/* Halcyon Threshold — minimal, readable, serious */

:root {
    --text: #1a1a1a;
    --text-muted: #555;
    --background: #fafaf9;
    --accent: #2c5282;
    --border: #e2e2e0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    font-size: 18px;
    line-height: 1.7;
}

body {
    font-family: Georgia, 'Times New Roman', serif;
    color: var(--text);
    background: var(--background);
    padding: 2rem 1rem;
    max-width: 42rem;
    margin: 0 auto;
}

main {
    display: flex;
    flex-direction: column;
    gap: 3rem;
}

header {
    text-align: center;
    padding: 2rem 0;
    border-bottom: 1px solid var(--border);
}

h1 {
    font-size: 2.2rem;
    font-weight: normal;
    letter-spacing: 0.02em;
    margin-bottom: 0.5rem;
}

.tagline {
    font-style: italic;
    color: var(--text-muted);
    font-size: 1.1rem;
}

h2 {
    font-size: 1.3rem;
    font-weight: normal;
    margin-bottom: 1rem;
    color: var(--accent);
}

section {
    padding-bottom: 1rem;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin-left: 1.5rem;
    margin-bottom: 1rem;
}

li {
    margin-bottom: 0.5rem;
}

a {
    color: var(--accent);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

footer {
    margin-top: 2rem;
    padding-top: 2rem;
    border-top: 1px solid var(--border);
    font-size: 0.85rem;
    color: var(--text-muted);
    text-align: center;
}

@media (max-width: 600px) {
    html {
        font-size: 16px;
    }

    h1 {
        font-size: 1.8rem;
    }
}
